			const T = {
				Nuevo: ["Nuevo pedido " + cod + " · " + r.getInt("total_pares") + " pares · " + dinero(r.getFloat("total"), d.mon) + " (sin pagar)", "Nuevo pedido sin pagar. Vence el " + esc(fechaCO(r.getString("vence_en"))) + "."],
